import math


def naive(z, y):
    try:
        p = 1 / (1 + math.exp(-z))
        return f"{-(y * math.log(p) + (1 - y) * math.log(1 - p)):.6g}"
    except (OverflowError, ValueError) as error:
        return type(error).__name__


def stable(z, y):
    return max(z, 0.0) + math.log1p(math.exp(-abs(z))) - y * z


for z, y in [(-1000.0, 0.0), (1000.0, 1.0), (40.0, 1.0), (40.0, 0.0), (-2.0, 1.0)]:
    print(f"z={z:7.1f} y={y:.0f} naive={naive(z, y)!s:>13} stable={stable(z, y):.6g}")

import math


def reconcile(attempts):
    accepted = {}
    for identity, value in attempts:
        if identity in accepted and accepted[identity] != value:
            raise ValueError(f"conflict for {identity}: {accepted[identity]} vs {value}")
        accepted[identity] = value
    return accepted


