import math

phi, sigma = 0.7, 0.5
series = {"a": [1.0, 0.9, 0.6, 0.5], "b": [-1.0, -0.7, -0.2, 0.1]}
stationary_var = sigma**2 / (1 - phi**2)


def initial(y):
    return 0.5 * (math.log(2 * math.pi * stationary_var) + y * y / stationary_var)


def transitions(values):
    return [
        0.5 * (math.log(2 * math.pi * sigma**2) + (cur - phi * prev) ** 2 / sigma**2)
        for prev, cur in zip(values, values[1:])
    ]


def complete(values):
    return initial(values[0]) + math.fsum(transitions(values))


print("stationary variance", round(stationary_var, 6))
print("complete", round(math.fsum(complete(v) for v in series.values()), 6))
print(
    "reset at t=2", round(math.fsum(complete(v[:2]) + complete(v[2:]) for v in series.values()), 6)
)
print("conditional", round(math.fsum(math.fsum(transitions(v)) for v in series.values()), 6))
print("a shuffled", round(complete([0.6, 1.0, 0.5, 0.9]), 6), "vs", round(complete(series["a"]), 6))

from itertools import combinations

values = [1.0, 3.0, 3.0, 3.0]
zero = (0, 0.0)


def reduce_rows(rows):
    return (len(rows), sum(rows))


def merge(a, b):
    return (a[0] + b[0], a[1] + b[1])


def merge_means(a, b):
    means = [s / n for n, s in (a, b) if n]
    return (a[0] + b[0], sum(means) / len(means) * (a[0] + b[0]) if means else 0.0)


results = {"merge": set(), "merge_means": set()}
for cut1, cut2 in combinations(range(len(values) + 1), 2):
    parts = [values[:cut1], values[cut1:cut2], values[cut2:]]
    for name, fn in (("merge", merge), ("merge_means", merge_means)):
        acc = zero
        for part in parts:
            acc = fn(acc, reduce_rows(part))
        results[name].add(acc)
print({name: sorted(found) for name, found in results.items()})
print("identity:", merge(zero, (4, 10.0)) == (4, 10.0), "empty:", reduce_rows([]))

import pandas as pd


def summarize(batches):
    for batch in batches:
        yield pd.DataFrame(
            {"n": [len(batch)], "total": [batch["y"].sum()], "ids": [len(set(batch["id"]))]}
        )


def first_batch_only(batches):
    batch = next(batches)
    yield pd.DataFrame(
        {"n": [len(batch)], "total": [batch["y"].sum()], "ids": [len(set(batch["id"]))]}
    )


frame = pd.DataFrame({"id": [11, 12, 13, 14, 15], "y": [1.0, 3.0, 3.0, 3.0, 5.0]})
for sizes in ([2, 2, 1], [5], [1, 1, 1, 1, 1]):
    starts = [sum(sizes[:i]) for i in range(len(sizes))]
    for fn in (summarize, first_batch_only):
        batches = iter([frame.iloc[s : s + size] for s, size in zip(starts, sizes)])
        out = pd.concat(fn(batches))
        n, total = int(out["n"].sum()), out["total"].sum()
        print(sizes, fn.__name__, "rows", n, "mean", total / n)

