import math
from dataclasses import dataclass


@dataclass(frozen=True)
class Dual:
    value: float
    tangent: float

    def __add__(self, b):
        return Dual(self.value + b.value, self.tangent + b.tangent)

    def __mul__(self, b):
        return Dual(self.value * b.value, self.tangent * b.value + self.value * b.tangent)

    def exp(self):
        e = math.exp(self.value)
        return Dual(e, e * self.tangent)


class HalfProduct(Dual):
    def __mul__(self, b):
        return HalfProduct(self.value * b.value, self.tangent * b.value)


for kind in (Dual, HalfProduct):
    out = [(x, (lambda d: d * d + d.exp())(kind(x, 1.0)).tangent) for x in (-1.0, 0.0, 1.0)]
    print(kind.__name__, [(x, round(t, 6)) for x, t in out])
print("analytic", [round(2 * x + math.exp(x), 6) for x in (-1.0, 0.0, 1.0)])
d = Dual(1.0, 2.0)
print("direction 2 at x=1:", round((d * d + d.exp()).tangent, 6), round(2 * (2 + math.e), 6))

targets = [0.0, 1.0, 2.0, 3.0, 4.0]


def epoch(w, velocity, lr=0.1, beta=0.9):
    for y in targets:
        velocity = beta * velocity + (w - y)
        w -= lr * velocity
    return w, velocity


w, v = 0.0, 0.0
for _ in range(4):
    w, v = epoch(w, v)
reference = w

w, v = 0.0, 0.0
for _ in range(2):
    w, v = epoch(w, v)
saved = {"w": w, "velocity": v, "epoch": 2}
full, weights_only = (saved["w"], saved["velocity"]), (saved["w"], 0.0)
for name, (w, v) in (("full state", full), ("weights only", weights_only)):
    for _ in range(2):
        w, v = epoch(w, v)
    print(f"{name:12} w={w:.6f} difference={w - reference:+.2e}")

import pandas as pd

frame = pd.DataFrame(
    {
        "group": ["A"] * 2 + ["B"] * 6 + ["C"],
        "y": [1.0, 3.0, 8.0, 10.0, 10.0, 12.0, 9.0, 11.0, 5.0],
    }
)


def fit_group(name, rows):
    n = len(rows)
    mean = rows["y"].mean()
    variance = ((rows["y"] - mean) ** 2).mean()
    if variance <= 0:
        return pd.DataFrame(
            [{"group": name, "n": n, "mu": None, "sigma2": None, "status": "degenerate scale"}]
        )
    return pd.DataFrame([{"group": name, "n": n, "mu": mean, "sigma2": variance, "status": "ok"}])


fits = pd.concat(fit_group(name, rows) for name, rows in frame.groupby("group"))
print(fits.to_string(index=False))

import struct

MACHINES = {62: "x86_64 (AMD64)", 183: "aarch64 (ARM64)"}


def elf_machine(header: bytes) -> str:
    if header[:4] != b"\x7fELF":
        raise ValueError("not an ELF shared object")
    order = "<" if header[5] == 1 else ">"
    (machine,) = struct.unpack(order + "H", header[18:20])
    return MACHINES.get(machine, f"unknown e_machine {machine}")


def fake_header(machine):
    return b"\x7fELF" + bytes([2, 1, 1]) + bytes(9) + struct.pack("<HH", 3, machine)


for machine in (62, 183):
    print(elf_machine(fake_header(machine)))
try:
    elf_machine(b"#!/bin/sh\n" + bytes(10))
except ValueError as error:
    print("rejected:", error)

import numpy as np

groups = {"g1": np.array([1.0, 2.0, 0.5]), "g2": np.array([-1.0, 0.0])}
sigma2, tau2 = 1.0, 2.0


def exact(y):
    cov = sigma2 * np.eye(len(y)) + tau2 * np.ones((len(y), len(y)))
    sign, logdet = np.linalg.slogdet(cov)
    return 0.5 * (len(y) * np.log(2 * np.pi) + logdet + y @ np.linalg.solve(cov, y))


def laplace(y):
    hessian = len(y) / sigma2 + 1 / tau2
    u = y.sum() / sigma2 / hessian
    joint = 0.5 * (len(y) * np.log(2 * np.pi * sigma2) + np.sum((y - u) ** 2) / sigma2)
    joint += 0.5 * (np.log(2 * np.pi * tau2) + u * u / tau2)
    return joint + 0.5 * np.log(hessian) - 0.5 * np.log(2 * np.pi)


for name, y in groups.items():
    print(name, round(exact(y), 10), round(laplace(y), 10))
print("total", round(sum(exact(y) for y in groups.values()), 10))

partitions = [[1.0, 3.0], [8.0, 10.0, 10.0, 12.0, 9.0, 11.0]]


def summaries(mu, scale_bug=False):
    total_loss = total_grad = 0.0
    for rows in partitions:
        factor = 1.0 / len(rows) if scale_bug else 1.0
        total_loss += factor * sum(0.5 * (y - mu) ** 2 for y in rows)
        total_grad += factor * sum(mu - y for y in rows)
    return total_loss, total_grad


for mu in (6.0, 8.0, 10.0):
    print(mu, summaries(mu), summaries(mu, scale_bug=True))

def classify(edges, partition):
    crossing = [(a, b) for a, b in edges if partition[a] != partition[b]]
    return ("B: keep coupling", crossing) if crossing else ("A: additive summaries", crossing)


